argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
Set-Location $repo;
$branch=(git branch --show-current).Trim();
$head=(git rev-parse HEAD).Trim();
$status=(git status --short);
$procs=Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'WebAIBridge|17448|server\.js|worker\.js' -and $_.CommandLine -notmatch 'E:\\manhwa' } | Select-Object ProcessId,ParentProcessId,Name,CommandLine;
$hits=@();
$patterns=@('reasoning_effort','extended_thinking','thinking effort','reasoning effort','Высок','Средний','high','medium');
foreach($p in $patterns){
  $m=Get-ChildItem "$repo\app" -Recurse -File -Include *.js,*.mjs,*.json,*.md,*.html | Select-String -Pattern $p -SimpleMatch -CaseSensitive:$false | Select-Object -First 40 Path,LineNumber,Line;
  if($m){$hits += [pscustomobject]@{pattern=$p;matches=@($m)}}
}
[pscustomobject]@{branch=$branch;head=$head;status=@($status);processes=@($procs);hits=@($hits)} | ConvertTo-Json -Depth 7 -Compress
